# Ejercicio T5-03 · Filtro: True si alguna palabra del texto está en prohibidas (en minúsculas).
# Ahora mismo «KATANA» se le escapa: pasa el texto a minúsculas antes de cortarlo.

def filtro(texto, prohibidas):
    palabras = texto.split()   # ← cambia esta línea
    for p in palabras:
        if p in prohibidas:
            return True
    return False

# Debería imprimir True:
print(filtro("quiero una KATANA", ["katana"]))
